5	{"name": "precedent_audit", "directory": "harnesses/precedent_audit", "hypothesis": "Selecting the units the pre-submit check re-opens by how well this question matches the reference cases that answer them (instead of by corpus frequency), naming the element that separates a draft unit from its attested relative so the facts rather than the commoner label decide, flagging draft units that are only one element of a reference unit, and matching the question's own recurring type wherever its header appears in the input, lifts the mean validation score above the 0.584 of iteration 3 by raising the weak side of the multi-unit task (recall 0.680 against precision 0.760, no sample over-predicting), without regressing the single-unit and free-form tasks.", "candidate_id": "dcb4cd6c08f4e1515bf9c5b9199ed71d2056ae6fc9d28878295e0c20964aa8c2", "split": "val", "spec": {"limit": null, "samples": 2}, "scores": {"USPTO": {"accuracy": 0.25, "correct": 15, "total": 60, "num_examples": 30, "aggregation": "sample_mean", "avg_f1": null, "micro_f1": null, "failed_samples": 0, "model_calls": 184, "input_tokens": 2050129, "output_tokens": 575901, "status": "ok", "successful_accuracy": 0.25, "successful_samples": 60, "expected_samples": 60, "completion_rate": 1.0, "missing_samples": 0, "errors": [], "error_counts": {}, "partial": false, "rankable": true, "memory_context_chars": 497.8, "attempt": 2, "reused_samples": 0}, "Symptom2Disease": {"accuracy": 0.89, "correct": 89, "total": 100, "num_examples": 50, "aggregation": "sample_mean", "avg_f1": null, "micro_f1": null, "failed_samples": 0, "model_calls": 319, "input_tokens": 2158663, "output_tokens": 280865, "status": "ok", "successful_accuracy": 0.89, "successful_samples": 100, "expected_samples": 100, "completion_rate": 1.0, "missing_samples": 0, "errors": [], "error_counts": {}, "partial": false, "rankable": true, "memory_context_chars": 2274.61, "attempt": 1, "reused_samples": 0}, "LawBench": {"accuracy": 0.55, "correct": 55, "total": 9